let compatible = null, detalle = '', confianza = 'baja', preguntaIdRaw = null;
try {
  const raw = ($json.output || '{}').toString().trim();
  const clean = raw.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(clean);
  compatible = !!parsed.compatible;
  detalle = (parsed.detalle || '').toString();
  confianza = (parsed.confianza || 'baja').toString().toLowerCase();
