Analiza a cual de las preguntas pendientes listadas corresponde la respuesta del equipo, y extraé el precio y/o stock que informo. Respondé UNICAMENTE con un JSON valido, sin texto adicional:
{"pregunta_id": <id de la pregunta que esta respondiendo, o null si no queda claro>, "precio": "precio informado o vacio si no lo dio", "stock": "stock informado (ej. 'hay stock', 'no hay', '3 unidades') o vacio si no lo dio", "detalle": "resumen breve", "confianza": "alta" o "baja"}

Usa "confianza": "baja" si la respuesta es ambigua, no da ni precio ni stock con claridad, no queda claro a cual pregunta corresponde (cuando hay mas de una pendiente), o el producto del que habla la respuesta no tiene nada que ver con el producto de la unica pregunta pendiente (en ese caso no asumas que es esa).

parameters.jsCode:
let precio = '', stock = '', detalle = '', confianza = 'baja', preguntaIdRaw = null;
try {
  const raw = ($json.output || '{}').toString().trim();
  const clean = raw.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(clean);
  precio = (parsed.precio || '').toString();
  stock = (parsed.stock || '').toString();
  detalle = (parsed.detalle || '').toString();
  confianza = (parsed.confianza || 'baja').toString().toLowerCase();
  preguntaIdRaw = parsed.pregunta_id;
} catch (e) {
  confianza = 'baja';
}

const pendientes = $('Buscar Pregunta Precio Pendiente').item.json.pendientes || [];
let match = pendientes.find(p => p.id === preguntaIdRaw) || null;
if (!match && pendientes.length > 0) {
  match = pendientes[pendientes.length - 1];
}
if (!match || (!precio && !stock)) {
  confianza = 'baja';
}

const escapar = (s) => s.replace(/'/g, "''");

return [{
  json: {
    precio, stock, detalle,
    precio_sql: escapar(precio), stock_sql: escapar(stock), detalle_sql: escapar(detalle),
    confianza,
    pregunta_id: match ? match.id : null,
    producto: match ? (match.producto || '') : '',
    producto_sql: escapar(match ? (match.producto || '') : '')
  }
}];

